633	+    public static List<String> normalize(List<String> tags) {
634	+        if (tags == null) {
635	+            return List.of();
636	+        }
637	+        Set<String> result = new LinkedHashSet<>();
638	+        tags.stream()
639	+                .filter(Objects::nonNull)
640	+                .map(tag -> tag.trim().toLowerCase(Locale.ROOT))
641	+                .filter(tag -> !tag.isEmpty())
642	+                .forEach(tag -> {
643	+                    if (tag.length() > MAX_TAG_LENGTH) {
